class Solution {
    public List<String> findAllConcatenatedWordsInADict(String[] words) {
        java.util.Arrays.sort(words, (a, b) -> a.length() - b.length());
        List<String> result = new java.util.ArrayList<>();
        java.util.Set<String> dict = new java.util.HashSet<>();
        for (String word : words) {
            if (word.isEmpty()) { dict.add(word); continue; }
            if (canForm(word, dict)) result.add(word);
            dict.add(word);
        }
        return result;
    }
    private boolean canForm(String word, java.util.Set<String> dict) {
        if (dict.isEmpty()) return false;
        int n = word.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                if (dp[j] && dict.contains(word.substring(j, i))) { dp[i] = true; break; }
            }
        }
        return dp[n];
    }
}
